const TITLE_NUM = /^CCC (\d+)/;

export function cccParagraphNumber(title: string): number | undefined {
  const match = title.match(TITLE_NUM);
  if (!match) return undefined;
  return Number(match[1]);
}

export function cccParagraphFor(title: string): string | undefined {
  const num = cccParagraphNumber(title);
  if (num == null) return undefined;
  return CCC_PARAGRAPH[num];
}

export function cccUrl(paragraph: number): string {
  const id = CCC_PAGE[paragraph];
  if (!id) {
    throw new Error(`No confirmed Vatican CCC page for paragraph ${paragraph}`);
  }
  return `https://www.vatican.va/archive/ENG0015/__${id}.HTM`;
}
